/* From Uiverse.io by JkHuger - Tags: select, option, emotion */
.__UIV_SCOPE__ .rating {
  cursor: pointer;
}

.__UIV_SCOPE__ .card {
  display: -webkit-box;
  display: -ms-flexbox;
  display: flex;
  margin: auto;
  -webkit-box-shadow: 0 0.5rem 1rem rgba(0, 0, 16, 0.19), 0 0.3rem 0.3rem rgba(0, 0, 16, 0.23);
  box-shadow: 0 0.5rem 1rem rgba(0, 0, 16, 0.19), 0 0.3rem 0.3rem rgba(0, 0, 16, 0.23);
  background-color: rgb(255, 255, 255);
  padding: 0.8rem;
  width: 33rem;
}

.__UIV_SCOPE__ .rating-container {
  display: -webkit-box;
  display: -ms-flexbox;
  display: flex;
  -webkit-box-pack: justify;
  -ms-flex-pack: justify;
  justify-content: space-between;
  padding: 0.4rem 0.8rem;
  width: 100%;
}

.__UIV_SCOPE__ .rating {
  background-color: rgba(0, 0, 16, 0.8);
  padding: 0.4rem 0.4rem 0.1rem 0.4rem;
  border-radius: 2.2rem;
}

.__UIV_SCOPE__ .rating-form {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
}

.__UIV_SCOPE__ .svg {
  fill: rgb(242, 242, 242);
  height: 3.6rem;
  width: 3.6rem;
  margin: 0.2rem;
  align-items: center;
  justify-content: center;
  cursor: pointer;
}

.__UIV_SCOPE__ .rating-form-2 svg {
  height: 3rem;
  width: 3rem;
  margin: 0.5rem;
}

.__UIV_SCOPE__ #radios label {
  position: relative;
}

.__UIV_SCOPE__ .super-happy, .__UIV_SCOPE__ [type="radio"] {
  position: absolute;
  opacity: 0;
}

.__UIV_SCOPE__ .input,.__UIV_SCOPE__ [type="radio"] + svg {
  -webkit-transition: all 0.2s;
  transition: all 0.2s;
}

.__UIV_SCOPE__ .super-happy[class="super-happy"]:hover + svg,
.__UIV_SCOPE__ .super-happy[class="super-happy"]:checked + svg,
.__UIV_SCOPE__ .super-happy[class="super-happy"]:focus + svg {
  fill: rgb(0, 204, 79);
  transition: 1.5s;
}

.__UIV_SCOPE__ .neutral[class="neutral"]:hover + svg,
.__UIV_SCOPE__ .neutral[class="neutral"]:checked + svg,
.__UIV_SCOPE__ .neutral[class="neutral"]:focus + svg {
  fill: rgb(232, 214, 0);
  transition: 1.5s;
}

.__UIV_SCOPE__ .super-sad[class="super-sad"]:hover + svg,
.__UIV_SCOPE__ .super-sad[class="super-sad"]:checked + svg,
.__UIV_SCOPE__ .super-sad[class="super-sad"]:focus + svg {
  fill: rgb(239, 42, 16);
  transition: 1.5s;
}
